static const RFNode* const TREES[TREE_COUNT] = {TREE_0, TREE_1, TREE_2, TREE_3, TREE_4, TREE_5, TREE_6, TREE_7, TREE_8, TREE_9, TREE_10, TREE_11, TREE_12, TREE_13, TREE_14, TREE_15, TREE_16, TREE_17, TREE_18, TREE_19, TREE_20, TREE_21, TREE_22, TREE_23, TREE_24, TREE_25, TREE_26, TREE_27, TREE_28, TREE_29};
static const uint16_t TREE_SIZES[TREE_COUNT] = {37, 43, 39, 33, 39, 23, 21, 15, 29, 43, 25, 21, 31, 31, 37, 25, 25, 39, 31, 59, 35, 41, 27, 37, 23, 45, 45, 19, 21, 45};

inline float predictTreeProbability(
    const RFNode* nodes,
    uint16_t nodeCount,
    const float features[FEATURE_COUNT]
) {
  int16_t nodeIndex = 0;
  uint16_t safetyCounter = 0;

  while (true) {
    if (nodeIndex < 0 || nodeIndex >= nodeCount) {
      return 0.0f;
    }

    const RFNode& node = nodes[nodeIndex];

    if (node.feature < 0) {
      const float total = node.normalWeight + node.anomalyWeight;

      if (total <= 0.0f) {
        return 0.0f;
      }

      return node.anomalyWeight / total;
    }

    const float value = features[node.feature];

    nodeIndex =
        value <= node.threshold
          ? node.left
          : node.right;

    safetyCounter++;

    if (safetyCounter > nodeCount) {
      return 0.0f;
    }
  }
}

inline float predictAnomalyProbability(
    const float features[FEATURE_COUNT]
) {
  float probabilityTotal = 0.0f;

  for (uint16_t treeIndex = 0; treeIndex < TREE_COUNT; treeIndex++) {
    probabilityTotal += predictTreeProbability(
      TREES[treeIndex],
      TREE_SIZES[treeIndex],
      features
    );
  }

  return probabilityTotal / static_cast<float>(TREE_COUNT);
}

inline uint8_t predictLabel(
    const float features[FEATURE_COUNT]
) {
  return
      predictAnomalyProbability(features) >= DECISION_THRESHOLD
        ? 1
        : 0;
}

